module pillar_collapse (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [15:0] strength_0,\n    input [15:0] strength_1,\n    input [15:0] strength_2,\n    input [15:0] strength_3,\n    output reg [15:0] max_damage,\n    output reg [3:0] best_pillar,\n    output reg done\n);\n\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] INIT = 3'd1;\n    localparam [2:0] SIM_LOOP = 3'd2;\n    localparam [2:0] SIM_DONE = 3'd3;\n    localparam [2:0] FINISHED = 3'd4;\n\n    reg [2:0] state;\n    reg [3:0] current_i;\n    reg [3:0] destroyed;\n    reg [31:0] load [0:3];\n    reg [3:0] queue [0:3];\n    reg [2:0] q_head, q_tail;\n    reg [3:0] damage_count;\n    reg [15:0] current_max_damage;\n    reg [3:0] current_best_pillar;\n\n    wire [15:0] strength [0:3];\n    assign strength[0] = strength_0;\n    assign strength[1] = strength_1;\n    assign strength[2] = strength_2;\n    assign strength[3] = strength_3;\n\n    integer i;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            max_damage <= 16'd0;\n            best_pillar <= 4'd0;\n            done <= 1'b0;\n            current_i <= 4'd0;\n            current_max_damage <= 16'd0;\n            current_best_pillar <= 4'd0;\n            destroyed <= 4'd0;\n            q_head <= 3'd0;\n            q_tail <= 3'd0;\n            damage_count <= 4'd0;\n            for (i = 0; i < 4; i = i + 1) begin\n                load[i] <= 32'd0;\n                queue[i] <= 4'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= INIT;\n                        current_i <= 4'd0;\n                        current_max_damage <= 16'd0;\n                        current_best_pillar <= 4'd0;\n                    end\n                end\n                \n                INIT: begin\n                    destroyed <= 4'd0;\n                    for (i = 0; i < 4; i = i + 1) begin\n                        load[i] <= 32'd1000;\n                    end\n                    destroyed[current_i] <= 1'b1;\n                    if (current_i > 0) begin\n                        load[current_i-1] <= load[current_i-1] + 32'd500;\n                    end\n                    if (current_i < (n - 4'd1)) begin\n                        load[current_i+1] <= load[current_i+1] + 32'd500;\n                    end\n                    q_head <= 3'd0;\n                    q_tail <= 3'd0;\n                    damage_count <= 4'd1;\n                    if ((current_i > 0) && (load[current_i-1] > strength[current_i-1])) begin\n                        queue[q_tail] <= current_i-1;\n                        q_tail <= q_tail + 3'd1;\n                    end\n                    if ((current_i < (n - 4'd1)) && (load[current_i+1] > strength[current_i+1])) begin\n                        queue[q_tail] <= current_i+1;\n                        q_tail <= q_tail + 3'd1;\n                    end\n                    state <= SIM_LOOP;\n                end\n                \n                SIM_LOOP: begin\n                    if (q_head != q_tail) begin\n                        if (!destroyed[queue[q_head]]) begin\n                            destroyed[queue[q_head]] <= 1'b1;\n                            damage_count <= damage_count + 4'd1;\n                            if ((queue[q_head] > 0) && !destroyed[queue[q_head]-1]) begin\n                                load[queue[q_head]-1] <= load[queue[q_head]-1] + (load[queue[q_head]] >> 1);\n                            end\n                            if ((queue[q_head] < (n - 4'd1)) && !destroyed[queue[q_head]+1]) begin\n                                load[queue[q_head]+1] <= load[queue[q_head]+1] + (load[queue[q_head]] >> 1);\n                            end\n                            if ((queue[q_head] > 0) && !destroyed[queue[q_head]-1] && (load[queue[q_head]-1] > strength[queue[q_head]-1])) begin\n                                queue[q_tail] <= queue[q_head]-1;\n                                q_tail <= q_tail + 3'd1;\n                            end\n                            if ((queue[q_head] < (n - 4'd1)) && !destroyed[queue[q_head]+1] && (load[queue[q_head]+1] > strength[queue[q_head]+1])) begin\n                                queue[q_tail] <= queue[q_head]+1;\n                                q_tail <= q_tail + 3'd1;\n                            end\n                        end\n                        q_head <= q_head + 3'd1;\n                    end else begin\n                        state <= SIM_DONE;\n                    end\n                end\n                \n                SIM_DONE: begin\n                    if (damage_count > current_max_damage) begin\n                        current_max_damage <= damage_count;\n                        current_best_pillar <= current_i;\n                    end\n                    if (current_i < (n - 4'd1)) begin\n                        current_i <= current_i + 4'd1;\n                        state <= INIT;\n                    end else begin\n                        state <= FINISHED;\n                    end\n                end\n                \n                FINISHED: begin\n                    max_damage <= current_max_damage;\n                    best_pillar <= current_best_pillar;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule